using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using DWSIM.Bridge.Editors;
using DWSIM.Bridge.Rpc;
using Newtonsoft.Json.Linq;
using NUnit.Framework;

namespace DWSIM.Bridge.Tests
{
    /// <summary>The unit operation editors generated by object.schema, and edits through them.</summary>
    [NonParallelizable]
    public class EditorSchemaTests
    {
        private sealed class Silent : INotifier
        {
            public void Notify(string method, JToken parameters) { }
        }

        private RpcRegistry _registry;

        [OneTimeSetUp]
        public void StartEngine()
        {
            _registry = new RpcRegistry();
            BridgeHost.Register(_registry, new SessionStore(), new Silent());
            BridgeHost.WarmUp();
        }

        private JToken Call(string method, object args)
            => _registry.Invoke(method, JObject.FromObject(args), CancellationToken.None);

        /// <summary>A flowsheet with water and methane under Peng-Robinson, in SI units.</summary>
        private string NewFlowsheet()
        {
            var id = Call("flowsheet.new", new { name = "editors" }).Value<string>("id");
            Call("flowsheet.addCompounds", new { flowsheetId = id, names = new[] { "Water", "Methane" } });
            Call("flowsheet.addPropertyPackage", new { flowsheetId = id, name = "Peng-Robinson (PR)" });
            Call("flowsheet.setUnitSystem", new { flowsheetId = id, name = "SI" });
            return id;
        }

        private static IEnumerable<JToken> Fields(JToken schema)
            => schema["sections"].SelectMany(s => s["fields"]);

        private static JToken Field(JToken schema, string label)
            => Fields(schema).FirstOrDefault(f => f.Value<string>("label") == label)
               ?? throw new AssertionException("no field labelled " + label + ": " + string.Join(", ", Fields(schema).Select(f => f.Value<string>("label"))));

        public static IEnumerable<string> CataloguedTypes() => EditorCatalog.CataloguedTypes
            .Concat(new[] { "Tank", "Pipe", "OrificePlate", "OT_Recycle", "OT_EnergyRecycle", "Filter", "SolidSeparator" })
            .Distinct();

        [TestCaseSource(nameof(CataloguedTypes))]
        public void EverySchemaBuildsWithItsInputsAndConnections(string type)
        {
            var fs = NewFlowsheet();
            var obj = Call("graph.add", new { flowsheetId = fs, type, x = 0, y = 0 }).Value<string>("id");
            var schema = Call("object.schema", new { flowsheetId = fs, id = obj });

            Assert.That(schema.Value<string>("type"), Is.EqualTo(type));
            var inputs = schema["sections"].Where(s => s.Value<string>("id") != "results").SelectMany(s => s["fields"]).ToList();
            Assert.That(inputs, Is.Not.Empty, "an editor with nothing to set");
            Assert.That(inputs.Select(f => f.Value<string>("label")), Has.None.EqualTo("Object class"));
            Assert.That(inputs.Select(f => f.Value<string>("label")), Has.None.EqualTo("Calculation Mode"));
            Assert.That(schema["connections"], Is.Not.Empty);
            foreach (var f in Fields(schema).Where(f => f["units"] != null))
                Assert.That(f["units"].Select(u => u.Value<string>()), Is.Unique, f.Value<string>("label") + " lists a unit twice");

            var entry = EditorCatalog.For(type);
            if (entry.Modes != null)
            {
                Assert.That(schema["mode"], Is.Not.Null.And.Not.TypeOf<JValue>(), "the catalog names a mode the object lacks");
                Assert.That(schema["mode"]["options"].Select(o => o.Value<string>("value")),
                    Is.EquivalentTo(entry.Modes.Select(m => m.value)), "every catalogued mode exists on the object");
            }
            Call("flowsheet.close", new { flowsheetId = fs });
        }

        [Test]
        public void TheHeaterModeDecidesWhatIsSpecified()
        {
            var fs = NewFlowsheet();
            var heater = Call("graph.add", new { flowsheetId = fs, type = "Heater", x = 0, y = 0 }).Value<string>("id");
            var schema = Call("object.schema", new { flowsheetId = fs, id = heater });
            Assert.That(schema["mode"].Value<string>("value"), Is.EqualTo("HeatAdded"));
            Assert.That(schema["mode"]["options"].Select(o => o.Value<string>("value")), Has.None.EqualTo("HeatAddedRemoved"), "hidden as in the Avalonia editor");
            Assert.That(Field(schema, "Heat Added").Value<bool>("editable"), Is.True);
            Assert.That(Field(schema, "Heat Added").Value<bool?>("missing"), Is.True, "the duty is unset");
            Assert.That(Field(schema, "Outlet Temperature").Value<bool>("editable"), Is.False);

            schema = Call("object.setMode", new { flowsheetId = fs, id = heater, value = "OutletTemperature" });
            Assert.That(Field(schema, "Heat Added").Value<bool>("editable"), Is.False);
            Assert.That(Field(schema, "Outlet Temperature").Value<bool>("editable"), Is.True);
            Assert.That(Field(schema, "Outlet Temperature")["units"].Select(u => u.Value<string>()), Does.Contain("C").And.Contain("K"));

            // A value in its own unit; the field reads back in the flowsheet's (SI).
            schema = Call("object.setField", new { flowsheetId = fs, id = heater, field = Field(schema, "Outlet Temperature").Value<string>("id"), value = 80.0, unit = "C" });
            Assert.That(Field(schema, "Outlet Temperature").Value<double>("value"), Is.EqualTo(353.15).Within(1e-9));
            Assert.That(Field(schema, "Outlet Temperature").Value<string>("unit"), Is.EqualTo("K"));

            var ex = Assert.Throws<RpcException>(() => Call("object.setField", new { flowsheetId = fs, id = heater, field = Field(schema, "Heat Added").Value<string>("id"), value = 10.0 }));
            Assert.That(ex.Message, Does.Contain("calculated in the current mode"));
            Assert.Throws<RpcException>(() => Call("object.setField", new { flowsheetId = fs, id = heater, field = "PROP_XX_9", value = 1.0 }));
            Assert.Throws<RpcException>(() => Call("object.setMode", new { flowsheetId = fs, id = heater, value = "Nonsense" }));
            Call("flowsheet.close", new { flowsheetId = fs });
        }

        [Test]
        public void AHeaterSetThroughItsEditorSolvesToItsOutletTemperature()
        {
            var fs = NewFlowsheet();
            var feed = Call("graph.add", new { flowsheetId = fs, type = "MaterialStream", x = 0, y = 0, tag = "feed" }).Value<string>("id");
            var heater = Call("graph.add", new { flowsheetId = fs, type = "Heater", x = 100, y = 0 }).Value<string>("id");
            var product = Call("graph.add", new { flowsheetId = fs, type = "MaterialStream", x = 200, y = 0, tag = "product" }).Value<string>("id");
            var duty = Call("graph.add", new { flowsheetId = fs, type = "EnergyStream", x = 100, y = 100 }).Value<string>("id");
            Call("graph.connect", new { flowsheetId = fs, sourceId = feed, sourcePort = "out-0", targetId = heater, targetPort = "in-0" });
            Call("graph.connect", new { flowsheetId = fs, sourceId = heater, sourcePort = "out-0", targetId = product, targetPort = "in-0" });
            Call("graph.connect", new { flowsheetId = fs, sourceId = duty, sourcePort = "out-0", targetId = heater, targetPort = "in-1" });
            Call("stream.specify", new
            {
                flowsheetId = fs, id = feed, temperature = 298.15, pressure = 101325.0, massFlow = 1.0,
                moleFractions = new Dictionary<string, double> { ["Water"] = 1.0, ["Methane"] = 0.0 }
            });

            var schema = Call("object.setMode", new { flowsheetId = fs, id = heater, value = "OutletTemperature" });
            Call("object.setField", new { flowsheetId = fs, id = heater, field = Field(schema, "Outlet Temperature").Value<string>("id"), value = 80.0, unit = "C" });
            var solved = Call("solve.run", new { flowsheetId = fs });
            Assert.That(solved.Value<bool>("ok"), Is.True, string.Join("; ", solved["errors"]));
            Assert.That(Call("stream.get", new { flowsheetId = fs, id = product }).Value<double>("temperature"), Is.EqualTo(353.15).Within(1e-6));

            schema = Call("object.schema", new { flowsheetId = fs, id = heater });
            Assert.That(schema.Value<bool>("calculated"), Is.True);
            Assert.That(schema["dof"].Value<int>("remaining"), Is.EqualTo(0));
            Assert.That(Field(schema, "Heat Added").Value<double>("value"), Is.GreaterThan(200), "about 230 kW to heat 1 kg/s of water by 55 K");
            var connections = schema["connections"];
            Assert.That(connections.First(c => c.Value<string>("port") == "in-0")["stream"].Value<string>("tag"), Is.EqualTo("feed"));
            Call("flowsheet.close", new { flowsheetId = fs });
        }

        [Test]
        public void TablesAndPickersWrite()
        {
            var fs = NewFlowsheet();

            var splitter = Call("graph.add", new { flowsheetId = fs, type = "Splitter", x = 0, y = 0 }).Value<string>("id");
            var schema = Call("object.setField", new { flowsheetId = fs, id = splitter, field = "split:0", value = 0.3 });
            Assert.That(Fields(schema).First(f => f.Value<string>("id") == "split:0").Value<double>("value"), Is.EqualTo(0.3));
            Assert.Throws<RpcException>(() => Call("object.setField", new { flowsheetId = fs, id = splitter, field = "split:0", value = 1.5 }));

            var separator = Call("graph.add", new { flowsheetId = fs, type = "ComponentSeparator", x = 0, y = 0 }).Value<string>("id");
            schema = Call("object.setField", new
            {
                flowsheetId = fs, id = separator, field = "table:separatorSplits",
                value = new JArray(new JObject { ["compound"] = "Water", ["spec"] = "PercentInletMassFlow", ["value"] = 95.0 },
                                   new JObject { ["compound"] = "Methane", ["spec"] = "MolarFlow", ["value"] = 2.0, ["unit"] = "mol/s" })
            });
            var rows = Fields(schema).First(f => f.Value<string>("id") == "table:separatorSplits")["rows"];
            Assert.That(rows.First(r => r.Value<string>("compound") == "Water").Value<double>("value"), Is.EqualTo(95.0));
            Assert.That(rows.First(r => r.Value<string>("compound") == "Methane").Value<string>("spec"), Is.EqualTo("MolarFlow"));

            var pipe = Call("graph.add", new { flowsheetId = fs, type = "Pipe", x = 0, y = 0 }).Value<string>("id");
            schema = Call("object.schema", new { flowsheetId = fs, id = pipe });
            var profile = Fields(schema).First(f => f.Value<string>("id") == "table:pipeProfile");
            var row = (JObject)profile["newRow"].DeepClone();
            row["length"] = 100.0;
            schema = Call("object.setField", new { flowsheetId = fs, id = pipe, field = "table:pipeProfile", value = new JArray(row, row.DeepClone()) });
            Assert.That(Fields(schema).First(f => f.Value<string>("id") == "table:pipeProfile")["rows"].Count(), Is.EqualTo(2));

            var column = Call("graph.add", new { flowsheetId = fs, type = "ShortcutColumn", x = 0, y = 0 }).Value<string>("id");
            schema = Call("object.setField", new { flowsheetId = fs, id = column, field = "compound:m_lightkey", value = "Methane" });
            Assert.That(Fields(schema).First(f => f.Value<string>("id") == "compound:m_lightkey").Value<string>("value"), Is.EqualTo("Methane"));
            Assert.Throws<RpcException>(() => Call("object.setField", new { flowsheetId = fs, id = column, field = "compound:m_heavykey", value = "Unobtainium" }));

            var valve = Call("graph.add", new { flowsheetId = fs, type = "Valve", x = 0, y = 0 }).Value<string>("id");
            schema = Call("object.setField", new { flowsheetId = fs, id = valve, field = "choice:FlowCoefficient", value = "Cv" });
            Assert.That(Fields(schema).First(f => f.Value<string>("id") == "choice:FlowCoefficient").Value<string>("value"), Is.EqualTo("Cv"));
            Call("flowsheet.close", new { flowsheetId = fs });
        }

        [Test]
        public void UnitsConvert()
        {
            Assert.That(Call("units.convert", new { value = 80.0, from = "C", to = "K" }).Value<double>(), Is.EqualTo(353.15).Within(1e-9));
            Assert.That(Call("units.convert", new { value = 1.0, from = "bar", to = "kPa" }).Value<double>(), Is.EqualTo(100.0).Within(1e-9));
            Assert.That(Call("units.convert", new { value = 5.0, from = "kW", to = "kW" }).Value<double>(), Is.EqualTo(5.0));
        }
    }
}
